client = get_opensearch_client()
if client.count(index="documents")["count"] > 0:
    print("Index already has documents, skipping load")
else:
    n = 0
    for source, chunks in DOCS.items():
        for text in chunks:
            client.index(index="documents", body={"content": text, "source": source, "embedding": get_embedding(text)})
            n += 1
    client.indices.refresh(index="documents")
    print("indexed chunks:", n)
print("count:", client.count(index="documents")["count"])
for q in ["What is the home office equipment allowance?", "Who won the 2022 FIFA World Cup?"]:
    print("\nQ:", q)
    for h in retrieve(q, top_k=2):
        print("  ", round(h["score"], 3), h["source"], "|", h["content"][:70])
